def candidate(token_ids, table, gamma, beta, w_in, w_out):
    tokens = table[token_ids]
    centered = tokens - jnp.mean(tokens, axis=-1, keepdims=True)
    spread = jnp.sqrt(jnp.mean(centered * centered, axis=-1, keepdims=True) + 1e-5)
    normalized = centered / spread * gamma + beta

    block = 128
    n_blocks = w_in.shape[1] // block
    in_blocks = w_in.reshape((w_in.shape[0], n_blocks, block)).transpose((1, 0, 2))
    out_blocks = w_out.reshape((n_blocks, block, w_out.shape[1]))

    def body(acc, xs):
        wi, wo = xs
        activation = jax.nn.gelu(normalized @ wi)
        return acc + activation @ wo, None

    hidden, _ = jax.lax.scan(body, jnp.zeros_like(tokens), (in_blocks, out_blocks))
    return tokens + hidden
