def candidate(token_ids, table, gamma, beta, w_in, w_out):
    tokens = table[token_ids]
    centered = tokens - jnp.mean(tokens, axis=-1, keepdims=True)
    spread = jnp.sqrt(jnp.mean(centered * centered, axis=-1, keepdims=True) + 1e-5)
    normalized = centered / spread * gamma + beta

    batch_size = 128
    n_batches = normalized.shape[0] // batch_size
    batches = normalized.reshape((n_batches, batch_size, normalized.shape[1]))
    token_batches = tokens.reshape((n_batches, batch_size, tokens.shape[1]))

    def body(_, xs):
        x, t = xs
        hidden = jax.nn.gelu(x @ w_in) @ w_out
        return None, t + hidden

    _, out = jax.lax.scan(body, None, (batches, token_batches))
    return out.reshape(tokens.shape)
